import { validateToolArguments } from "@earendil-works/pi-ai";
import { describe, expect, it } from "vitest";
import { createNestedSubagentTools } from "../src/nested-tools.js";

const STORED = {
	profile: "balanced",
	systemPrompt: "Stored guidance.",
	inheritContext: true,
	isolated: true,
	pair: true,
	maxTurns: 7,
	runInBackground: false,
};

function setup() {
	const records = new Map<string, any>();
	const resumeCalls: Array<{ id: string; prompt: string; options: any }> = [];
	const spawnCalls: any[] = [];
	const makeRecord = (id: string, parentAgentId: string) => ({
		id,
		type: "builder",
		description: "stored",
		parentAgentId,
		status: "completed",
		result: `RESULT-${id}`,
		session: {},
		invocation: { ...STORED },
	});
	records.set("owned", makeRecord("owned", "parent-1"));
	records.set("foreign", makeRecord("foreign", "someone-else"));
	const manager = {
		getRecord: (id: string) => records.get(id),
		resume: async (id: string, prompt: string, _signal?: AbortSignal, options?: any) => {
			resumeCalls.push({ id, prompt, options });
			const record = records.get(id);
			if (!record) return undefined;
			record.status = "completed";
			record.result = `RESUMED-${resumeCalls.length}`;
			return record;
		},
		spawn: (...args: any[]) => {
			spawnCalls.push(args);
			return "spawned";
		},
		spawnAndWait: async (...args: any[]) => {
			spawnCalls.push(args);
			throw new Error("spawn must not happen during resume");
		},
		steer: () => false,
		abort: () => false,
	};
	const tools = createNestedSubagentTools({
		manager: manager as any,
		pi: {} as any,
		parentAgentId: "parent-1",
		depth: 1,
		maxSubagentDepth: 2,
		allowedSubagents: "all",
		configCwd: process.cwd(),
		projectTrusted: false,
	});
	const agentTool = tools.find((tool) => tool.name === "agent") as any;
	const call = async (args: Record<string, unknown>, id = "owned") => {
		const validated = validateToolArguments(agentTool, {
			type: "toolCall",
			id: "call-1",
			name: "agent",
			arguments: { prompt: "continue", description: "continue", subagent_type: "builder", resume: id, ...args },
		} as any);
		return agentTool.execute("call-1", validated, undefined, undefined, {} as any);
	};
	return { records, resumeCalls, spawnCalls, call };
}

describe("nested public agent resume policy (acceptance)", () => {
	it("reuses stored true inherit_context/isolated (and other fixed settings) when omitted", async () => {
		const { records, resumeCalls, call } = setup();
		const result = await call({});
		expect(result.isError).not.toBe(true);
		expect(resumeCalls).toHaveLength(1);
		expect(resumeCalls[0].id).toBe("owned");
		expect(records.get("owned").invocation).toEqual(STORED);
	});

	it("accepts explicitly matching fixed settings", async () => {
		const { resumeCalls, call } = setup();
		const result = await call({
			inherit_context: true,
			isolated: true,
			pair: true,
			profile: "balanced",
			system_prompt: "Stored guidance.",
		});
		expect(result.isError).not.toBe(true);
		expect(resumeCalls).toHaveLength(1);
	});

	it("treats blank guidance as omission", async () => {
		const { resumeCalls, call } = setup();
		const result = await call({ system_prompt: "   " });
		expect(result.isError).not.toBe(true);
		expect(resumeCalls).toHaveLength(1);
	});

	it.each([
		["inherit_context", { inherit_context: false }],
		["isolated", { isolated: false }],
		["pair", { pair: false }],
		["profile", { profile: "quick" }],
		["system_prompt", { system_prompt: "Different guidance." }],
	])("rejects an explicit conflicting %s before resume and leaves stored choices unchanged", async (_name, args) => {
		const { records, resumeCalls, spawnCalls, call } = setup();
		const result = await call(args);
		expect(result.isError).toBe(true);
		expect(resumeCalls).toHaveLength(0);
		expect(spawnCalls).toHaveLength(0);
		expect(records.get("owned").invocation).toEqual(STORED);
	});

	it("allows foreground/background selection to change per invocation", async () => {
		const { resumeCalls, call } = setup();
		const background = await call({ run_in_background: true });
		expect(background.isError).not.toBe(true);
		const foreground = await call({ run_in_background: false });
		expect(foreground.isError).not.toBe(true);
		const omitted = await call({});
		expect(omitted.isError).not.toBe(true);
		expect(resumeCalls).toHaveLength(3);
		expect(resumeCalls[0].options?.isBackground).toBe(true);
		expect(resumeCalls[1].options?.isBackground ?? false).toBe(false);
		expect(resumeCalls[2].options?.isBackground ?? false).toBe(false);
	});

	it("keeps ownership checks before any resume", async () => {
		const { resumeCalls, call } = setup();
		const foreign = await call({}, "foreign");
		expect(foreign.isError).toBe(true);
		const missing = await call({}, "missing");
		expect(missing.isError).toBe(true);
		expect(resumeCalls).toHaveLength(0);
	});
});

import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fauxAssistantMessage, fauxText, validateToolArguments } from "@earendil-works/pi-ai";
import { registerFauxProvider } from "@earendil-works/pi-ai/compat";
import { afterAll, describe, expect, it } from "vitest";
import { fauxModelBackend } from "../../../tests/helpers/faux-model.js";
import { installWorkManager } from "../../shared/src/work-manager.js";
import installSubagents from "../src/index.js";

const previousAgentDir = process.env.PI_CODING_AGENT_DIR;
const isolatedAgentDir = mkdtempSync(join(tmpdir(), "apple-pi-acceptance-agent-"));
process.env.PI_CODING_AGENT_DIR = isolatedAgentDir;

afterAll(() => {
	if (previousAgentDir === undefined) delete process.env.PI_CODING_AGENT_DIR;
	else process.env.PI_CODING_AGENT_DIR = previousAgentDir;
	rmSync(isolatedAgentDir, { recursive: true, force: true });
});

describe("root public agent resume policy (acceptance)", () => {
	it("reuses stored fixed settings on omission, accepts matches, rejects conflicts", async () => {
		const cwd = mkdtempSync(join(tmpdir(), "apple-pi-acceptance-root-"));
		mkdirSync(join(cwd, ".pi", "agents"), { recursive: true });
		writeFileSync(
			join(cwd, ".pi", "agents", "policy-test.md"),
			`---
name: policy-test
description: resume policy test
tools: read
extensions: false
skills: false
persist_session: false
---
Answer the task.
`,
		);
		writeFileSync(join(cwd, ".pi", "subagents.json"), JSON.stringify({ maxConcurrent: 2 }));
		const faux = registerFauxProvider({
			provider: "faux",
			models: [{ id: "faux-policy", contextWindow: 200_000 }],
		});
		let calls = 0;
		const respond = () => {
			calls += 1;
			return fauxAssistantMessage([fauxText(`REPLY-${calls}`)]);
		};
		faux.setResponses(Array.from({ length: 12 }, () => respond));
		const model = faux.getModel();
		const runtime = fauxModelBackend(model);
		const tools = new Map<string, any>();
		const lifecycle = new Map<string, (...args: any[]) => any>();
		const busListeners = new Map<string, Set<(payload: unknown) => void>>();
		const pi = {
			registerMessageRenderer: () => {},
			registerTool: (tool: any) => tools.set(tool.name, tool),
			registerCommand: () => {},
			registerShortcut: () => {},
			on: (event: string, handler: (...args: any[]) => any) => lifecycle.set(event, handler),
			events: {
				emit: (name: string, payload: any) => {
					for (const listener of busListeners.get(name) ?? []) listener(payload);
				},
				on: (name: string, listener: (payload: unknown) => void) => {
					const listeners = busListeners.get(name) ?? new Set();
					listeners.add(listener);
					busListeners.set(name, listeners);
					return () => listeners.delete(listener);
				},
			},
			sendMessage: () => {},
			exec: async () => ({ code: 1, stdout: "", stderr: "" }),
		} as any;
		const previousCwd = process.cwd();
		process.chdir(cwd);
		try {
			installWorkManager(pi);
			installSubagents(pi);
			const tool = tools.get("agent");
			expect(tool).toBeDefined();
			const ctx = {
				cwd,
				model,
				modelRegistry: runtime.modelRegistry,
				getSystemPrompt: () => "parent",
				sessionManager: { getSessionFile: () => undefined, getBranch: () => [] },
				isProjectTrusted: () => true,
				hasUI: false,
			} as any;
			const run = (id: string, args: Record<string, unknown>) =>
				tool.execute(
					id,
					validateToolArguments(tool, {
						type: "toolCall",
						id,
						name: "agent",
						arguments: { description: "policy", subagent_type: "policy-test", ...args },
					} as any),
					undefined,
					undefined,
					ctx,
				);

			const first = await run("start", {
				prompt: "start",
				inherit_context: true,
				isolated: true,
				pair: false,
				system_prompt: "Stored guidance.",
			});
			expect(first.isError).not.toBe(true);
			const firstText = first.content[0].text as string;
			expect(firstText).toContain("REPLY-1");
			const agentId = firstText.match(/Agent ID: ([^\s]+)/)?.[1];
			expect(agentId).toBeTruthy();

			const omitted = await run("omitted", { prompt: "continue", resume: agentId });
			expect(omitted.isError).not.toBe(true);
			expect(omitted.content[0].text).toContain("REPLY-2");

			const matching = await run("matching", {
				prompt: "continue",
				resume: agentId,
				inherit_context: true,
				isolated: true,
				pair: false,
				system_prompt: "Stored guidance.",
			});
			expect(matching.isError).not.toBe(true);
			expect(matching.content[0].text).toContain("REPLY-3");

			const blank = await run("blank", { prompt: "continue", resume: agentId, system_prompt: "   " });
			expect(blank.isError).not.toBe(true);
			expect(blank.content[0].text).toContain("REPLY-4");

			for (const conflict of [
				{ inherit_context: false },
				{ isolated: false },
				{ pair: true },
				{ system_prompt: "Different guidance." },
			]) {
				const rejected = await run("conflict", { prompt: "continue", resume: agentId, ...conflict });
				expect(rejected.isError).toBe(true);
			}
			expect(calls).toBe(4);

			const background = await run("background", {
				prompt: "continue",
				resume: agentId,
				run_in_background: true,
			});
			expect(background.isError).not.toBe(true);
			const settled = await tools.get("get_subagent_result").execute("wait", { agent_id: agentId }, undefined);
			expect(settled.content[0].text).toContain("REPLY-5");

			const foreground = await run("foreground", {
				prompt: "continue",
				resume: agentId,
				run_in_background: false,
			});
			expect(foreground.isError).not.toBe(true);
			expect(foreground.content[0].text).toContain("REPLY-6");

			const fresh = await run("fresh", { prompt: "fresh" });
			expect(fresh.isError).not.toBe(true);
			const freshId = (fresh.content[0].text as string).match(/Agent ID: ([^\s]+)/)?.[1];
			expect(freshId).toBeTruthy();
			const freshInherit = await run("fresh-inherit", { prompt: "x", resume: freshId, inherit_context: true });
			expect(freshInherit.isError).toBe(true);
			const freshIsolated = await run("fresh-isolated", { prompt: "x", resume: freshId, isolated: true });
			expect(freshIsolated.isError).toBe(true);
			const freshFalse = await run("fresh-false", {
				prompt: "x",
				resume: freshId,
				inherit_context: false,
				isolated: false,
			});
			expect(freshFalse.isError).not.toBe(true);

			const missing = await run("missing", { prompt: "x", resume: "does-not-exist" });
			expect(missing.isError).toBe(true);
		} finally {
			await lifecycle.get("session_shutdown")?.();
			process.chdir(previousCwd);
			faux.unregister();
			rmSync(cwd, { recursive: true, force: true });
		}
	}, 60_000);
});
